```json
{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "category": "electrodomesticos_cocina",
        "attributes": {
          "tipo": "freidora de aire"
        },
        "limit": 5
      }
    },
    {
      "id": "s2",
      "op": "get_product",
      "args": {
        "id": "$s1.0.id"
      }
    },
    {
      "id": "s3",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.0.id",
        "limit": 3
      }
    },
    {
      "id": "s4",
      "op": "get_product",
      "args": {
        "id": "$s1.1.id"
      }
    },
    {
      "id": "s5",
      "op": "compare_products",
      "args": {
        "ids": ["$s1.0.id", "$s1.1.id"]
      }
    },
    {
      "id": "s6",
      "op": "respond",
      "plantilla": "Para cocinar más sano con poco aceite, te recomiendo estas freidoras de aire:\n\n1. {nombre1} <<rec:{id1}>> - ${precio1} CLP\n   Potencia: {potencia1}W | Capacidad: {capacidad1}L | Material: {material1}\n\n2. {nombre2} <<rec:{id2}>> - ${precio2} CLP\n   Potencia: {potencia2}W | Capacidad: {capacidad2}L | Material: {material2}\n\nComparación: <<cmp:{id1},{id2}>>\n{comparacion}\n\nAmbas son excelentes opciones para freír con mínimo aceite. ¿Te gustaría conocer más detalles de alguna?",
      "vars": {
        "nombre1": "$s2.name",
        "id1": "$s2.id",
        "precio1": "$s2.price_clp",
        "potencia1": "$s2.attributes.potencia_w",
        "capacidad1": "$s2.attributes.capacidad_litros",
        "material1": "$s2.attributes.material",
        "nombre2": "$s4.name",
        "id2": "$s4.id",
        "precio2": "$s4.price_clp",
        "potencia2": "$s4.attributes.potencia_w",
        "capacidad2": "$s4.attributes.capacidad_litros",
        "material2": "$s4.attributes.material",
        "comparacion": "La más barata es {mas_barato} y la mejor evaluada es {mejor_evaluado}."
      }
    }
  ]
}
